WITH base AS (SELECT *, CEIL(discount_pct) AS discount_pct_whole, CASE WHEN promo_code IN ('WELCOME5', 'VIP') THEN 'Priority' ELSE 'Other' END AS promo_code_group FROM promotions WHERE promo_code NOT IN ('VIP', 'BUNDLE', 'WELCOME5')) SELECT id, channel, promo_code, starts_on, discount_pct, LEAD(discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on, id) AS next_discount_pct, LAG(discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on, id) AS prev_discount_pct, LAG(discount_pct_whole) OVER (PARTITION BY promo_code ORDER BY ends_on, id) AS prev_discount_pct_whole, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on, id) AS row_seq, CUME_DIST() OVER (PARTITION BY channel, promo_code ORDER BY discount_pct_whole DESC) AS discount_pct_whole_cume_dist FROM base;
